"""The `00 Start Here` page: manifest, naming rules, component rules and the gate command (NodeSpec for apply_spec)."""
import spec_kit as kit


def start_here(plan, n_icons, n_styles):
    lines = [("Title / Semibold", "DESIGN:OS Studio UI"),
             ("Body / Regular", f"The Studio chrome drawn as a design system: {len(plan['semantic'])} Semantic variables, {len(plan['primitives'])} Primitives, "
                                f"{n_styles} text styles, {n_icons} icons."),
             ("Large / Semibold", "Variables"),
             ("Body / Regular", "Primitives: hidden, value-derived steps. Semantic: one alias per theme.rs constant, named group/name."),
             ("Body / Regular", "Array elements are numbered from 0, like their code syntax. Components bind Semantic only."),
             ("Large / Semibold", "Primitive colour names"),
             ("Body / Regular", "A colour that equals a Tailwind v3 palette value takes its name: neutral/950, yellow/50, orange/500, base/white."),
             ("Body / Regular", "Any other colour is hue/step. Hue: the nearest Tailwind hue in OKLCH, or neutral when chroma is below 0.02."),
             ("Body / Regular", "Step: round((1 - L) * 1000 / 50) * 50, clamped to 25-975, with L the OKLab lightness."),
             ("Body / Regular", "A taken name adds -2, -3, and Tailwind's own names are taken: an off-palette colour never takes a Tailwind name."),
             ("Body / Regular", "An alpha colour is the name of its opaque colour plus -a<alpha%>."),
             ("Body / Regular", "The step is lightness, so a derived step can be darker than a lower Tailwind step (orange/350-2 vs orange/500)."),
             ("Large / Semibold", "Pages"),
             ("Body / Regular", "00 Start Here, 01 Foundations, 02 Core, 03 Studio, 04 Screens, 99 Archive."),
             ("Large / Semibold", "Component rules"),
             ("Body / Regular", "Disabled is half alpha per paint (kit/mod.rs:134-162 half_color): every visible paint of a State=Disabled variant has"),
             ("Body / Regular", "opacity 0.5, every other variant 1.0, and a node never carries an opacity. There is no opacity/disabled variable: theme.rs has no constant."),
             ("Body / Regular", "Disabled is sticky: every paint inside a Disabled variant, or inside a nested instance of a Disabled variant at any depth, carries 0.5. "
                                "A non-Disabled variant may nest a Disabled control, and a Disabled variant nests only the Disabled variant of each control it holds "
                                "(an Icon glyph is the one exception)."),
             ("Body / Regular", "Tabs/Segmented State=Disabled is a deviation (2026-10-31): the app never draws a disabled segmented (state_of(.., true), widgets/kit/tabs.rs:101)."),
             ("Body / Regular", "So the variant is the whole strip disabled: both cells take segmented_look(Disabled) (kit/tabs.rs:46) and the shell is at 0.5."),
             ("Body / Regular", "Icon/Glyph Size Sm = 16 = LAYER_ICON_SIZE, Md = 20. Button/Icon Size Sm carries a 20 px glyph = the kit's icon_px(Sm): the names differ."),
             ("Body / Regular", "Focus/Ring is one main (radius 12 = RADIUS_CONTROL + SPACE_FACT). A ring rings the node it sits in, its host (kit/focus.rs:36-38):"),
             ("Body / Regular", "it is that parent grown by SPACE_FACT on every side, at (-4, -4), and each corner is round(parent radius + SPACE_FACT)."),
             ("Body / Regular", "A radius binds through the four corner keys only: 0.7.5 draws a bound radius at the variable's value and ignores a uniform cornerRadius binding."),
             ("Body / Regular", "So a radius binding on a ring instance is forbidden. Its radius is a literal, and the gate reads the host from the ring's parent, never from the allow-list."),
             ("Body / Regular", "Focus/Ring radius on a non-12 host is a pinned literal (2026-10-31): the engine cannot bind a sum."),
             ("Body / Regular", "A checkbox rings its 16 px box, not its control rect (kit/choice.rs:104-111): a checkbox variant makes the box the ring's parent."),
             ("Body / Regular", "A slider handle rings a pill frame, never an Ellipse: radius = height / 2, so the ring keeps the main's 12 (kit/choice.rs:159-162)."),
             ("Body / Regular", "A node named Focus ring that is not an instance of a Focus/Ring variant fails the gate, and a ring's four corners are one radius (kit/focus.rs:38)."),
             ("Body / Regular", "Swatch/Color: the layer named Color is the swatch's content, and an instance may override that layer's fill and nothing else (2026-10-31)."),
             ("Body / Regular", "The override allowance is recorded here, not gated yet: the file gate reads pages 01-03, and a screen has its own rule (below)."),
             ("Body / Regular", "Search hint colour (D5 deviation, issue #1389): Input/Search draws its hint in TEXT_PLACEHOLDER, the colour the painters name."),
             ("Body / Regular", "0.7.5 draws about #9A9A9A: egui replaces a hint's colour with weak_text_color (TEXT at alpha 0.6, 154 over BG) and neither search painter sets it."),
             ("Body / Regular", "TEXT at 0.6 opacity would match, but the G2 opacity rule allows opacity on a State=Disabled paint only. #1389 sets the placeholder colour once at theme level."),
             ("Body / Regular", "Input/Field Xs draws its own hint in TEXT_TERTIARY (widgets/field.rs:98-101, 711-716), so it is no deviation."),
             ("Body / Regular", "Inline colour literals (D5 deviation, Popover/ColorPicker): the app draws these from Color32 literals that no theme constant holds."),
             ("Body / Regular", "The component draws the nearest theme tone by value, even a hover role: the largest per-channel difference against every opaque colour constant."),
             ("Body / Regular", "Contrast ink 0xE4E4E7 -> TEXT_SECONDARY_HOVER (distance 2); badge text 0x4CC58B -> TEXT_SUCCESS (25)."),
             ("Body / Regular", "Badge surface 0x17302A -> BG_SUCCESS_PRIMARY (20, the nearest success surface; a neutral is 15 away but loses the green)."),
             ("Body / Regular", "Hue thumb 0xFF0000 -> BG_ERROR_SOLID (38); alpha thumb and thumb ring 0xFFFFFF -> ICON (0)."),
             ("Body / Regular", "Swatch edge white at alpha 0x1A -> BORDER_TRANSLUCENT (0). The thumb halo (black at alpha 0x4D) is omitted."),
             ("Body / Regular", "A colour at an alpha of its own keeps its rgb and carries the alpha in the colour, never in a paint opacity:"),
             ("Body / Regular", "the Ready-for-dev pill is DEV_READY.gamma_multiply(0.22),"),
             ("Body / Regular", "rgb (20, 174, 92) at alpha 56, one allow-list entry with the Rust line. A paint opacity other than 0.5 on a Disabled paint, or 1.0, fails G2."),
             ("Large / Semibold", "Regions and screens"),
             ("Body / Regular", "A region (03 Studio, row Regions) is sized to its rect in the capture's layout.json (tab bar 1440 x 32, rail 49 x 868, panels 241 x 868, canvas 909 x 868)."),
             ("Body / Regular", "Its children are placed where the painter puts them, and a named widget carries the layout.json key as its node name (rail-File, pages-toggle, share-button)."),
             ("Body / Regular", "A region nests the components as instances and draws locally only what no component draws; it never reuses a kit, client or library name for its default content."),
             ("Body / Regular", "A screen (04 Screens) is a frame named after its registry screen record, 1440 x 900, instances only: the regions and components, plus one rectangle,"),
             ("Body / Regular", "the page's own colour behind the canvas content (the document's, not chrome). A screen shows no kit, client or library name: the texts a kit supplied are neutral."),
             ("Body / Regular", "Limits that make a region differ from production: swapped 20 px tool glyphs render at 16 px in designos-mcp 0.7.5 (#1427, the file carries the Size override),"),
             ("Body / Regular", "and a nested instance's glyph cannot be exposed as a property of its host (#1471), so the shared headers choose theirs by parts:"),
             ("Body / Regular", "Panel/Header (Show Collapse action,"),
             ("Body / Regular", "Show Add action: Layers is ChevronDown and Search) and Section/Header (Show Opacity action: the Page title's action)."),
             ("Body / Regular", "A screen's render of its capture has a cap on the mean difference of each region"),
             ("Body / Regular", "(rail 2.6, left panel 2.7, right panel 6.9, tab bar 0.4, rulers 7.1, toolbar 3.8, screen 4.6)"),
             ("Body / Regular", "and on the worst 40 px tile (34): the first screen's measure plus about 8 %. The 99th percentile is reported, never capped (text edges dominate it)."),
             ("Body / Regular", "A region nests the components as instances and draws locally only what no component draws; it never reuses a kit, client or library name for its"),
             ("Body / Regular", "default content."),
             ("Body / Regular", "the page's own colour behind the canvas content (the document's, not chrome). A screen shows no kit, client or library name: the texts a kit supplied"),
             ("Body / Regular", "are neutral."),
             ("Body / Regular", "Panel/RightInspector State=Page, Frame, Layers, Text, Instance, Prototype, Dev: the inspector of the capture's selection (panels/properties.rs"),
             ("Body / Regular", "selection_ui :823, typography.rs section :160, components.rs component_props :378, prototype.rs selection_sections :224; Dev is right.rs show :11)."),
             ("Body / Regular", "Tree/Row Depth=0..5: a layer row indented 16 px a level (panels/layers.rs :538); a screen's names follow production's row rule (split_row_text"),
             ("Body / Regular", ":235-241, elide :653)."),
             ("Body / Regular", "Panel/DevInspect State=Inspect, Annotate, Component, List: Dev mode's right content (dev/sections.rs, panels/inspect.rs :338, dev/playground.rs :451)"),
             ("Body / Regular", "and its left list (dev/list.rs show :123)."),
             ("Body / Regular", "Navigation/BottomCanvasToolbar State=Move, Comment, AI, Dev, DevAnnotate: the active tool (panels/toolbar.rs show) and the 266 px Dev dock"),
             ("Body / Regular", "(show_dev_mode_toolbar :370, dev_tools :421)."),
             ("Body / Regular", "Navigation/LeftRail Tool=File, Agents, Assets, Variables: the tile of the open panel selected (panels/rail.rs show)."),
             ("Body / Regular", "Window/Variables Layout=Full, Floating, Present: the full window, the 642 x 380 floating window (variables/view.rs floating_rect :88) and the"),
             ("Body / Regular", "presentation panel (present.rs paint_vars_panel :804)."),
             ("Body / Regular", "Popover/Panel Kind=Default plus 15 kinds, one settings popover each (widgets/popover.rs :17, style_edit.rs :111, effects.rs, stroke.rs, typography.rs"),
             ("Body / Regular", ":596, prototype.rs :518, image_jobs.rs :1334 and :1440, comments/thread.rs :122, skills/mod.rs :816, agent_approval_card.rs :205)."),
             ("Body / Regular", "Dialog/Modal Kind=Libraries, Plugins, InstallPlugin, Compare: libraries/modal.rs :173, plugins/ui.rs :17 and :47, dev/compare.rs :83."),
             ("Body / Regular", "Popover/ColorPicker Kind=Fill, Page, Gradient: the picker of a paint, of the page colour (widgets/picker.rs :763) and of a gradient (:912)."),
             ("Body / Regular", "Panel/AgentTerminal State=Picker, Chat, Failure, Approval: the new-session picker with its five probed rows (Show probed, signed in, unknown and"),
             ("Body / Regular", "checking n: agent_picker.rs), the session tab strip and PTY view (terminal.rs :5986-6054), the start-failure card (agent_start_failure.rs :233) and"),
             ("Body / Regular", "the approval card (agent_approval_card.rs :51)."),
             ("Body / Regular", "Banner/Inline Tone=Neutral, Success, Warning, Error: the version-history bar (history/banner.rs :9); Warning and Error follow agent_session_failure.rs"),
             ("Body / Regular", "paint_banner :871 in v0.7.6, Success takes the Neutral look."),
             ("Body / Regular", "Menu/Item Show check column: a menu with a checkable row puts every label at 32, or 60 with an icon (widgets/menu.rs Layout :166, has_check)."),
             ("Body / Regular", "Tabs/Segmented Show cell 3: the third cell of the vector edit bar (canvas/vector.rs toolbar :1110)."),
             ("Body / Regular", "Navigation/TopTabBar Show project tab, Show Home selected, Show dev tile: the tab strip of Home and of Dev mode (tabs.rs :971, :1045)."),
             ("Body / Regular", "Navigation/TopTabBar Show unsaved dot: production's dirty-tab marker, shown on any tab with unsaved changes (tabs.rs :1085)."),
             ("Body / Regular", "Bar/Presentation Show Variables active: the Variables toggle on while its panel is open (present.rs paint_vars_panel :804)."),
             ("Large / Semibold", "Gates"),
             ("Mono / Value", "python3 scripts/check_studio_ui_file.py design/studio-ui.designos")]
    return kit.column("Manifest", [kit.text(f"Line {i + 1}", t, style=st, width=900) for i, (st, t) in enumerate(lines)], gap="space/group")
